// scripts/lib/daily-assignment.mjs 增加从 control.dispatches 中读取 queued 状态的任务
// 替换 dailyAssignment 函数中 control 相关逻辑：
// 修改后支持两种 control 结构：
// 1) 旧结构 control.dispatches 数组 + control.date
// 2) 新结构 control.dispatches 数组，其中任务带 status='queued_for_next_daily_economy' 且 agent 匹配
export function dailyAssignment(agent, date, { control, pulse } = {}) {
  const controlDispatches = Array.isArray(control?.dispatches) ? control.dispatches : [];
  const explicit = controlDispatches.find(t => t.agent === agent && typeof t.instruction === 'string' && t.instruction.trim() && (t.status === 'queued_for_next_daily_economy' || t.status === 'queued'));
  if (explicit) return { id: explicit.id || `CONTROL-${date}-${agent}`, instruction: explicit.instruction, source: control.dispatch_source || 'actual_model_review' };
  const explicitByDate = control?.date === date ? controlDispatches.find(t => t.agent === agent && typeof t.instruction === 'string' && t.instruction.trim()) : null;
  if (explicitByDate) return { id: explicitByDate.id || `CONTROL-${date}-${agent}`, instruction: explicitByDate.instruction, source: control.dispatch_source || 'coordinator_record' };
  const board = Array.isArray(pulse?.task_board) ? pulse.task_board : [];
  const directed = board.find(t => t.date === date && t.assigned_to === agent && t.status === 'assigned');
  if (directed) return { id: directed.id, instruction: directed.instruction, source: 'pulse_direct_assignment' };
  const baseline = baselineDispatches(date).find(t => t.agent === agent);
  if (baseline) return { id: baseline.id, instruction: baseline.instruction, source: 'coordinator_rules_zero_model_baseline' };
  const open = board.find(t => t.date === date && t.status === 'available' && !t.assigned_to);
  if (open) return { id: open.id, instruction: open.instruction, source: 'self_discovered_available_task_not_claim_proof' };
  return null;
}
